// "2026-07-13" → "2026년 7월 13일"(방침 머리의 시행·공고·개정일 표기).
function policyDateLabel(ymd = POLICY_REVISION_DATE) {
  const [y, m, d] = String(ymd || "").split("-").map((part) => Number(part));
  return y && m && d ? `${y}년 ${m}월 ${d}일` : String(ymd || "");
}

