  const monthDueNet = monthDueIncome - monthDueExpense;
  // V22.9.76: "이번 달 나갈 정기지출" 아래 건수·이름에는 지출 항목만 쓴다(수당이 나갈 돈으로 적혔다).
  const monthDueOut = monthDue.filter((st) => !isIncomeReservePlan(st.plan));
