  const nav = selected ? renderUnifiedNav("keyword-guide", { month, householdId: selected.id, householdName: householdChoiceLabelV229118(selected, households) || selected.name, role: String(selected.role || "") }) : "";
  // V22.9.40 (B): 광고 자리는 편집기 아래의 읽기 전용 "카테고리별 추천 예시" 뒤 하나뿐이다.
  const adKey = "/keyword-guide";
