async function handleMyProfileUpdate(request, env) {
  const userId = await verifyUserSession(request, env);
  if (!userId) return redirectResponse("/my");
  const form = await request.formData();
  const nickname = mergedMarkerFreeName(String(form.get("nickname") || ""), 80);
  if (!nickname) return redirectResponse("/my/profile?err=nickname_missing");
  // V22.9.126 FC-27i: 저장 실패가 500 안전모드 화면으로 떨어졌다. 실패를 알리고 프로필 화면으로 돌아간다.
  try {
    await supabase(env, `/rest/v1/users?id=eq.${encodeURIComponent(userId)}`, {
      method: "PATCH",
      headers: { Prefer: "return=minimal" },
      body: JSON.stringify({ nickname }),
    });
  } catch (err) {
    rememberOpsEvent({ kind: "my_profile_update_failed", severity: "warn", path: "/my/profile", method: "POST", detail: safeError(err) });
    const notice = isUncertainStorageWrite(err) ? "저장 결과를 확인하지 못했습니다. 화면을 새로고침해 이름이 바뀌었는지 먼저 확인해 주세요." : "표시 이름을 저장하지 못했습니다. 기존 이름은 그대로입니다. 잠시 후 다시 시도해 주세요.";
    return redirectResponse(`/my/profile?err=${encodeURIComponent(notice)}`);
  }
  return redirectResponse("/my/profile?msg=updated");
}

function renderMyProfileHtml({ env, user, msg = "", err = "" }) {
  const title = escapeHtml(appName(env));
  return `<!doctype html><html lang="ko"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"/><title>${title} · 프로필</title><style>body{margin:0;background:#f6f7f9;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{max-width:640px;margin:0 auto;padding:18px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:22px;padding:18px;box-shadow:0 10px 26px rgba(15,23,42,.06)}input{width:100%;height:44px;border:1px solid #cbd5e1;border-radius:14px;padding:0 12px;font:inherit}button,.btn{height:42px;border:0;border-radius:14px;background:#111827;color:#fff;text-decoration:none;font-weight:950;padding:0 14px;display:inline-flex;align-items:center}.muted{color:#64748b;font-size:13px;line-height:1.6}.notice{background:#eff6ff;color:#1e3a8a;border:1px solid #bfdbfe;border-radius:14px;padding:12px;line-height:1.55}.ok{background:#e8f1e9;color:#365b41;border:1px solid #c9decf;border-radius:12px;padding:10px;margin-bottom:10px}.error{background:#f7e8e4;color:#8f463d;border:1px solid #e7c4bd;border-radius:12px;padding:10px;margin-bottom:10px}</style></head><body><main class="wrap"><h1>내 프로필</h1>${msg ? `<div class="ok">${formatMessage(msg)}</div>` : ""}${err ? `<div class="error">${escapeHtml(err)}</div>` : ""}<section class="card"><form method="post" action="/my/profile"><p class="muted">가계부 참여자 명단과 지출자 표시 이름으로 사용됩니다.</p><div class="notice">이 이름을 수정해도 로그인 이름과 비밀번호는 바뀌지 않습니다.</div><p><label>표시 이름</label></p><input name="nickname" value="${escapeHtml(user?.nickname || "")}" placeholder="예: Bin, 엄마, 아빠"/><p><button type="submit">저장</button> <a class="btn" href="/my" style="background:#e2e8f0;color:#111">내 가계부</a></p></form></section></main></body></html>`;
}

function renderCategoryAdminHtml({ env, households, selected, householdId, custom = [], displayCategories = [], msg = "", err = "" }) {
  const title = escapeHtml(appName(env));
  const presets = DEFAULT_CATEGORIES.map((c) => `<span class="pill">${escapeHtml(c)}</span>`).join("");
  const categoryCards = displayCategories.length ? displayCategories.map((c) => {
    const keywords = normalizeCategoryKeywords(c.keywords || "");
    const keywordText = keywords.join(", ");
    const keywordChips = keywords.length ? keywords.map((k) => `<span class="kw">${escapeHtml(k)}</span>`).join("") : `<span class="emptyKw">키워드 없음</span>`;
    const isCustom = !String(c.id || "").startsWith("default_") && c.storage !== "default" && c.storage !== "default_keyword";
    const deleteForm = isCustom ? `<form method="post" action="/admin/category/delete"><input type="hidden" name="household_id" value="${escapeHtml(c.household_id || householdId)}"/><input type="hidden" name="id" value="${escapeHtml(c.id)}"/><button class="danger" type="submit">삭제</button></form>` : `<span class="baseBadge">기본</span>`;
    return `<div class="catCard"><div class="catHead"><div><b>${escapeHtml(c.name)}</b><span>${c.type === "income" ? "수입" : "지출"}</span></div>${deleteForm}</div><div class="kwBox">${keywordChips}</div><div class="suggestBox"><strong>추천 키워드</strong>${keywordGuideChips(c.name, c.type, keywords)}</div><form class="kwForm" method="post" action="/admin/category-keywords/save"><input type="hidden" name="household_id" value="${escapeHtml(c.household_id || householdId)}"/><input type="hidden" name="type" value="${escapeHtml(c.type || "expense")}"/><input type="hidden" name="name" value="${escapeHtml(c.name)}"/><input name="keywords" value="${escapeHtml(keywordText)}" placeholder="예: 스타벅스, 커피, 투썸"/><button class="primary" type="submit">키워드 저장</button></form></div>`;
  }).join("") : `<p class="muted">분류를 선택하거나 내 분류를 추가하면 키워드를 관리할 수 있습니다.</p>`;
  return `<!doctype html><html lang="ko"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"/><title>${title} · 분류 설정</title><style>*,*::before,*::after{box-sizing:border-box}body{margin:0;background:#f6f7fb;color:#111827;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans KR",sans-serif}.wrap{max-width:1120px;margin:0 auto;padding:16px}.hero{background:linear-gradient(135deg,#111827,var(--ab12-action,#2563eb));color:#fff;border-radius:28px;padding:22px;margin:12px 0;box-shadow:0 18px 42px rgba(15,23,42,.18)}.hero h1{margin:0;font-size:28px}.hero p{line-height:1.55;opacity:.92}.card{background:#fff;border:1px solid #e5e7eb;border-radius:24px;padding:18px;margin:12px 0;box-shadow:0 10px 28px rgba(15,23,42,.055)}.filters,.formGrid,.kwForm{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;margin-top:10px}.filters select,.filters button,.formGrid input,.formGrid select,.formGrid button,.kwForm input,.kwForm button{height:44px;border:1px solid #d1d5db;border-radius:14px;padding:0 12px;background:#fff;font:inherit}.filters button,.formGrid button,.kwForm button{background:#111827;color:#fff;font-weight:1000}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:10px}.catCard{background:#f8fafc;border:1px solid #e5e7eb;border-radius:20px;padding:14px}.catHead{display:flex;align-items:center;justify-content:space-between;gap:10px}.catHead b{display:block;font-size:17px}.catHead span,.muted{color:#64748b;font-size:13px;line-height:1.45}.pill,.kw,.emptyKw,.baseBadge,.kwSuggest{display:inline-flex;border-radius:999px;padding:6px 10px;margin:3px;font-size:12px;font-weight:900}.pill{background:#f1f5f9;border:1px solid #e2e8f0}.kw{background:#e0f2fe;color:#075985}.kwSuggest{border:1px solid #bfdbfe;background:#eff6ff;color:#1d4ed8;cursor:pointer}.emptyKw{background:#f1f5f9;color:#64748b}.baseBadge{background:#ecfdf5;color:#065f46}.danger{height:34px;border:0;border-radius:11px;background:#fee2e2;color:#991b1b;font-weight:900;padding:0 10px}.ok{background:#e8f1e9;color:#365b41;border:1px solid #c9decf;border-radius:12px;padding:10px}.error{background:#f7e8e4;color:#8f463d;border:1px solid #e7c4bd;border-radius:12px;padding:10px}.tip{background:#ecfdf5;border:1px solid #a7f3d0;color:#065f46;border-radius:16px;padding:12px;line-height:1.55}@media(max-width:760px){.wrap{padding:12px}.hero h1{font-size:24px}.filters,.formGrid,.kwForm{grid-template-columns:1fr}}</style></head><body>${renderUnifiedNav("categories", { householdId, role: "admin" })}<main class="wrap"><section class="hero"><h1>분류·키워드 설정</h1><p>같은 단어라도 집마다 분류 기준이 다를 수 있습니다. 예를 들어 “커피”를 식비로 볼 수도 있고, 용돈으로 볼 수도 있습니다. 우리집 기준에 맞게 키워드를 연결하세요.</p><form class="filters" method="get" action="/categories"><select name="household_id"><option value="">가계부 선택</option>${households.map((h) => `<option value="${escapeHtml(h.id)}" data-household-name="${escapeHtml(householdChoiceLabelV229118(h, households) || h.name || "가계부")}"${h.id === householdId ? " selected" : ""}>${escapeHtml(householdChoiceLabelV229118(h, households) || h.name)}</option>`).join("")}</select><button type="submit">조회</button></form></section>${msg ? `<div class="ok">${formatMessage(msg)}</div>` : ""}${err ? `<div class="error">${escapeHtml(err)}</div>` : ""}<section class="card"><h2>내 분류 추가</h2><div class="guideLine">키워드는 순서와 상관없이 동작합니다. 대신 “가족이 실제로 입력할 말”을 넣어야 자동분류가 잘 됩니다. 예: 커피, 스벅, 스타벅스, 점심, 주유, 자동차보험 <a href="/keyword-guide" style="font-weight:1000;color:#1d4ed8">키워드 안내 보기</a></div><form class="formGrid" method="post" action="/admin/category/create"><input type="hidden" name="household_id" value="${escapeHtml(householdId || selected?.id || "")}"/><input name="name" placeholder="예: 용돈, 아이간식, 렌즈소모품"/><select name="type"><option value="expense">지출</option><option value="income">수입</option></select><input name="keywords" placeholder="키워드 예: 커피, 스벅, 편의점"/><button type="submit">추가</button></form><p class="tip">키워드는 쉼표로 여러 개 입력할 수 있습니다. 챗봇 입력과 카드/문자 내역 분류에 우선 반영됩니다.</p></section><section class="card"><h2>기본 분류</h2><p class="muted">기본 분류도 키워드를 연결할 수 있습니다.</p><div>${presets}</div></section><section class="card"><h2>키워드 관리</h2><div class="grid">${categoryCards}</div></section><script>function addKeywordToInput(btn){var form=btn.closest(".catCard")?.querySelector(".kwForm");if(!form)return;var input=form.querySelector('input[name="keywords"]');if(!input)return;var kw=btn.getAttribute("data-kw")||btn.textContent.trim();var parts=input.value.split(/[,\n|/]+/).map(function(x){return x.trim()}).filter(Boolean);if(!parts.some(function(x){return x.toLowerCase()===kw.toLowerCase()})){parts.push(kw)}input.value=parts.join(", ");input.focus()}</script></main></body></html>`;
}

async function handleAdminBulkUpdate(request, env) {
  let form = null;
  let month = currentMonthKst();
  let householdId = "";
  try {
    if (!(await verifyAdminSession(request, env))) return redirectResponse("/?legacy=1");
    form = await request.formData();
    const ids = [...new Set(form.getAll("ids").map((x) => String(x || "").trim()).filter(Boolean))];
    month = validMonth(String(form.get("month") || "")) || currentMonthKst();
    householdId = String(form.get("household_id") || "").trim();

    if (!ids.length) {
      return redirectResponse(returnLocation(form, transactionReturnFallback(month, householdId, { err: "선택된 거래가 없습니다." }), { err: "선택된 거래가 없습니다." }));
    }
    if (!householdId) {
      return redirectResponse(returnLocation(form, transactionReturnFallback(month, householdId, { err: "가계부를 먼저 선택하세요." }), { err: "가계부를 먼저 선택하세요." }));
    }
    const targets = await fetchTransactionRowsByIds(env, ids);
    if (targets.length !== ids.length || targets.some((row) => String(row.household_id || "") !== householdId)) {
      return redirectResponse(returnLocation(form, transactionReturnFallback(month, householdId, { err: "선택 거래에 다른 가계부 기록이 섞여 있어 작업을 취소했습니다." }), { err: "선택 거래에 다른 가계부 기록이 섞여 있어 작업을 취소했습니다." }));
    }

    if (String(form.get("bulk_delete") || "") === "1") {
      await bulkTransactionsAtomic(env, ids, householdId, {}, { actorKind: "admin_bulk", delete: true });
      // V22.9.81 U-18: 성공 안내는 코드로 보낸다. 예전에는 ‘N건 삭제 완료’ 자유 문장이 코드를 덮어써, 화면의 formatMessage 가 모르는 값으로 읽고
      // ‘요청을 처리하지 못했습니다’(실패 문장)를 초록 성공 칸에 보였다.
      return redirectResponse(returnLocation(form, transactionReturnFallback(month, householdId, { msg: "bulk_deleted" }), { msg: "bulk_deleted" }));
    }

    const patch = {};
    const bulkType = String(form.get("bulk_quick_type") || form.get("bulk_type") || "").trim();
    const category = String(form.get("bulk_category") || "").trim();
    const payment = String(form.get("bulk_payment_method") || "").trim();
    const date = String(form.get("bulk_transaction_date") || "").trim();
    const userId = String(form.get("bulk_user_id") || "").trim();
    if (bulkType === "income" || bulkType === "expense") patch.type = bulkType;
    if (category) patch.category = category;
    if (payment || String(form.get("clear_payment_method") || "") === "1") patch.payment_method = payment;
    if (date) {
      if (!isValidTransactionDateString(date)) {
        return redirectResponse(returnLocation(form, transactionReturnFallback(month, householdId, { err: "날짜 형식이 올바르지 않습니다." }), { err: "날짜 형식이 올바르지 않습니다." }));
      }
      patch.transaction_date = date;
    }
    if (userId) {
      const members = await fetchHouseholdMembers(env, householdId);
      if (!activeSpenderExists(members, userId)) {
        return redirectResponse(returnLocation(form, transactionReturnFallback(month, householdId, { err: "선택한 지출자가 이 가계부의 참여자가 아닙니다." }), { err: "선택한 지출자가 이 가계부의 참여자가 아닙니다." }));
      }
      patch.user_id = userId;
    }

    if (!Object.keys(patch).length) {
      return redirectResponse(returnLocation(form, transactionReturnFallback(month, householdId, { err: "변경할 값이 없습니다." }), { err: "변경할 값이 없습니다." }));
    }

    // V22.9.80 T-12: 환불과 연결돼 트리거가 막는 기록은 빼고 나머지만 고친다. 연결된 기록이 없으면 예전과 같은 한 번의 요청이다.
    const outcome = await bulkUpdateSkippingRefundLocks(env, ids, householdId, patch, { actorKind: "admin_bulk" });
    if (outcome.skipped.length) {
      const note = `선택한 ${ids.length}건 중 ${outcome.updatedIds.length}건을 수정했습니다. 환불과 연결돼 바꿀 수 없는 ${outcome.skipped.length}건은 그대로 두었습니다. 연결은 정산 화면의 ‘환불·환급’에서 풀 수 있습니다.`;
      return redirectResponse(returnLocation(form, transactionReturnFallback(month, householdId, { err: note }), { err: note }));
    }
    // V22.9.81 U-18: 일괄 수정 성공도 코드(bulk_updated)로 보낸다(자유 문장 ‘N건 일괄 수정 완료’는 화면에서 실패 문장으로 보였다).
    return redirectResponse(returnLocation(form, transactionReturnFallback(month, householdId, { msg: "bulk_updated" }), { msg: "bulk_updated" }));
  } catch (err) {
    rememberOpsEvent({ kind: "transaction_bulk_update_failed", severity: "warn", path: "/admin/transactions/bulk", method: "POST", detail: safeError(err) });
    // V22.9.80 T-12: 트리거가 막았는데 막힌 기록을 가려내지 못했거나 모두 막혔으면 아무것도 바뀌지 않았다. 이유를 그대로 알린다.
    // V22.9.94 C-11(외부 검토): 결과를 모르는 실패(응답 없음·시한·5xx — 저장소는 이미 지웠거나 바꿨을 수 있다)에도 ‘기존 기록은 유지됩니다’라고 했고,
    // 일괄 삭제에도 ‘수정하지 못했습니다’라고 했다. 이제 결과 모름은 다시 보내지 말고 목록부터 확인하라고 알리고(이 화면으로 돌아오면 목록을 새로 읽는다),
    // 거절(4xx·검증)만 ‘기존 기록은 유지됩니다’다. 삭제와 수정 문장을 나눈다.
    const isDelete = String(form?.get?.("bulk_delete") || "") === "1";
    const message = refundLinkLockedReason(err)
      ? "환불과 연결된 기록이 있어 아무것도 바꾸지 않았습니다. 연결은 정산 화면의 ‘환불·환급’에서 먼저 풀어 주세요."
      : isUncertainStorageWrite(err)
        ? (isDelete
          ? "삭제 결과를 확인하지 못했습니다. 같은 요청을 다시 보내지 말고, 목록을 새로 고쳐 선택한 기록이 지워졌는지 먼저 확인해 주세요."
          : "일괄 수정 결과를 확인하지 못했습니다. 같은 요청을 다시 보내지 말고, 목록을 새로 고쳐 바뀌었는지 먼저 확인해 주세요.")
        : isDelete
          ? "선택한 거래내역을 삭제하지 못했습니다. 기존 기록은 유지됩니다."
          : "선택한 거래내역을 수정하지 못했습니다. 기존 기록은 유지됩니다.";
    const fallback = transactionReturnFallback(month, householdId, { err: message });
    return redirectResponse(form ? returnLocation(form, fallback, { err: message }) : fallback);
  }
}

async function bulkDeleteTransactions(env, ids) {
  const cleanIds = [...new Set((ids || []).map((id) => String(id || "").trim()).filter((id) => /^[0-9a-fA-F-]{20,80}$/.test(id)))];
  if (!cleanIds.length) return { deleted: 0, failed: ids.length, error: "삭제 가능한 거래 ID가 없습니다." };

  let deleted = 0;
  let failed = 0;
  let lastError = "";

  for (let i = 0; i < cleanIds.length; i += 80) {
    const chunk = cleanIds.slice(i, i + 80);
    const params = new URLSearchParams();
    params.set("id", `in.(${chunk.join(",")})`);
    try {
      await supabase(env, `/rest/v1/transactions?${params.toString()}`, {
        method: "DELETE",
        headers: { Prefer: "return=minimal" },
      });
      deleted += chunk.length;
    } catch (err) {
      lastError = safeError(err);
      for (const id of chunk) {
        try {
          await supabase(env, `/rest/v1/transactions?id=eq.${encodeURIComponent(id)}`, {
            method: "DELETE",
            headers: { Prefer: "return=minimal" },
          });
          deleted += 1;
        } catch (innerErr) {
          failed += 1;
          lastError = safeError(innerErr);
        }
      }
    }
  }
  return { deleted, failed, error: lastError };
}

function returnLocation(form, fallback, extra = {}) {
  const raw = String(form.get("return_to") || "");
  // V22.9.76 감사 C-2: 정규화 전 문자열만 보면 "/.//x"(정규화하면 "//x")나 "/\x"·중간에 탭이 낀 경로(브라우저가 "//x"로 읽음)가
  // 다른 사이트 주소로 나갈 수 있었다. 정규화한 뒤에도 같은 사이트 경로인지 보는 관리자 복귀 경로 검사를 통과해야 쓴다.
  let path = raw && safeAdminReturnPath(raw, "") ? raw : fallback;
  if (Object.keys(extra).length) {
    const u = new URL(path, "https://dummy.local");
    for (const [k, v] of Object.entries(extra)) if (v !== undefined && v !== null && String(v) !== "") u.searchParams.set(k, String(v));
    path = u.pathname + u.search + u.hash;
  }
  return path;
}

function safeUserReturnPath(raw = "", fallback = "/my/households") {
  const value = String(raw || "").trim();
  if (!value.startsWith("/") || value.startsWith("//") || /[\\\r\n]/.test(value)) return fallback;
  let parsed;
  try { parsed = new URL(value, "https://accountbook.local"); }
  catch (err) { return fallback; }
  const allowed = [
    "/my", "/app", "/menu", "/budgets", "/settlement-summary", "/keyword-guide",
    "/reserve-plans", "/budget-alerts", "/meeting-households", "/household-create-join",
  ];
  const ok = allowed.some((prefix) => parsed.pathname === prefix || parsed.pathname.startsWith(prefix + "/"));
  return ok ? `${parsed.pathname}${parsed.search}${parsed.hash}` : fallback;
}

async function handleImportTemplateCsv(request, env) {
  if (!(await verifyAdminSession(request, env))) return redirectResponse("/?legacy=1");
  const header = ["날짜","구분","금액","분류","내용","결제수단","지출자"];
  const rows = [
    ["2026-06-18","지출","12000","식비","점심","카드",""],
    ["2026-06-18","지출","4500","카페/간식","커피","카카오페이",""],
    ["2026-06-25","수입","3000000","급여","월급","계좌이체",""],
  ];
  const csv = [header, ...rows].map(r => r.map(csvCell).join(",")).join("\n");
  return new Response("\ufeff" + csv, {
    headers: {
      "content-type": "text/csv; charset=utf-8",
      "content-disposition": `attachment; filename="accountbook_import_template.csv"`,
      "cache-control": "no-store",
    },
  });
}

async function handleImportTemplateXls(request, env) {
  if (!(await verifyAdminSession(request, env))) return redirectResponse("/?legacy=1");
  const html = `<!doctype html><html><head><meta charset="utf-8"></head><body><table border="1"><thead><tr><th>날짜</th><th>구분</th><th>금액</th><th>분류</th><th>내용</th><th>결제수단</th><th>지출자</th></tr></thead><tbody><tr><td>2026-06-18</td><td>지출</td><td>12000</td><td>식비</td><td>점심</td><td>카드</td><td></td></tr><tr><td>2026-06-18</td><td>지출</td><td>4500</td><td>카페/간식</td><td>커피</td><td>카카오페이</td><td></td></tr><tr><td>2026-06-25</td><td>수입</td><td>3000000</td><td>급여</td><td>월급</td><td>계좌이체</td><td></td></tr></tbody></table></body></html>`;
  return new Response(html, {
    headers: {
      "content-type": "application/vnd.ms-excel; charset=utf-8",
      "content-disposition": `attachment; filename="accountbook_import_template.xls"`,
      "cache-control": "no-store",
    },
  });
}

const ADMIN_IMPORT_MAX_ROWS = 3000;
const ADMIN_IMPORT_BATCH_ROWS = 1000;

async function handleAdminImportJson(request, env) {
  if (!MY_IMPORT_WRITES_ENABLED_V22959) return jsonResponse({ ok: false, error: "import_recovery_read_only", message: "복구 모드에서는 가져오기를 저장하지 않습니다. 원본과 기존 미리보기를 보관해 주세요." }, 503);
  try {
    if (!(await verifyAdminSession(request, env))) return jsonResponse({ ok: false, error: "unauthorized", message: "로그인 세션이 만료되었습니다. 새로고침 후 다시 로그인하세요." }, 401);
    const body = await readJson(request);
    const householdId = typeof body.household_id === "string" ? body.household_id.trim() : "";
    if (!householdId) return jsonResponse({ ok: false, error: "household_id_required", message: "가계부를 먼저 선택해주세요." }, 400);
    const rawText = String(body.raw_text || "");
    const defaultUserId = String(body.user_id || "").trim();
    const members = await fetchHouseholdMembers(env, householdId);
    if (!defaultUserId || !activeSpenderExists(members, defaultUserId)) {
      return jsonResponse({ ok: false, error: "spender_required", message: "업로드 기본 지출자를 현재 가계부 참여자 중에서 선택해주세요." }, 400);
    }
    const parsed = parseImportedRecords(rawText, householdId, defaultUserId);
    // V22.9.76 감사 E-8: 예전에는 1,000행을 넘는 부분을 말없이 버리고(건너뜀 0건), 행 id 를 요청마다 새로 만들어 응답이 끊긴 뒤
    // 같은 파일을 다시 내면 두 번 저장됐다. 이제 id 를 (가계부·기본 지출자·원문, 행 순서)로 정해 같은 파일을 다시 제출해도 이미
    // 저장된 행은 건너뛴다. 저장은 1,000행씩 나눠 최대 ADMIN_IMPORT_MAX_ROWS 행까지 하고(저장소 호출: 묶음당 1번 + 확인 80행당 1번),
    // 그보다 많거나 파일을 끝까지 읽지 못했으면 아무것도 저장하지 않고 나눠 올리라고 답한다.
    const cleaned = cleanImportedRowsForInsert(parsed.rows);
    if (parsed.analysis_complete === false || cleaned.length > ADMIN_IMPORT_MAX_ROWS) {
      return jsonResponse({ ok: false, error: "import_too_many_rows", rows: cleaned.length, max_rows: ADMIN_IMPORT_MAX_ROWS, message: `저장할 수 있는 행이 ${numberWithCommas(cleaned.length)}행${parsed.analysis_complete === false ? " 넘게 있어" : "이라"} 아무것도 저장하지 않았습니다. 한 번에 ${numberWithCommas(ADMIN_IMPORT_MAX_ROWS)}행까지 가져올 수 있으니 파일을 나눠 올려 주세요.` }, 413);
    }
    const idSeed = `admin:${await sha256Hex(`${householdId}|${defaultUserId}|${rawText}`)}`;
    const rows = [];
    for (const [index, row] of cleaned.entries()) rows.push({ ...row, id: row.id || await myImportDeterministicTransactionId(idSeed, index + 1), user_id: row.user_id || defaultUserId });
    if (!rows.length) return jsonResponse({ ok: false, error: "no_valid_rows", message: "저장 가능한 행을 찾지 못했습니다.", skipped: parsed.skipped }, 400);
    if (rows.some((row) => !activeSpenderExists(members, row.user_id))) return jsonResponse({ ok: false, error: "spender_not_member", message: "가져오기 행의 지출자가 현재 가계부의 활성 참여자가 아닙니다." }, 400);
    let inserted = 0, duplicates = 0, committedRows = 0;
    try {
      for (let start = 0; start < rows.length; start += ADMIN_IMPORT_BATCH_ROWS) {
        const batch = rows.slice(start, start + ADMIN_IMPORT_BATCH_ROWS);
        const result = await commitImportedTransactionRows(env, householdId, batch);
        const summary = Array.isArray(result) ? result[0] : result;
        if (!Number.isInteger(summary?.inserted) || !Number.isInteger(summary?.duplicates) || summary.inserted < 0 || summary.duplicates < 0 || summary.inserted + summary.duplicates !== batch.length) throw Object.assign(new Error("import_summary_invalid"), { importSummaryInvalid: true });
        inserted += summary.inserted;
        duplicates += summary.duplicates;
        committedRows += batch.length;
      }
    } catch (err) {
      if (!committedRows && !isUncertainStorageWrite(err) && !err?.importSummaryInvalid) throw err;
      rememberOpsEvent({ kind: "admin_import_unconfirmed", severity: "error", path: "/admin/import/json", method: "POST", detail: safeError(err) });
      return jsonResponse({ ok: false, error: "import_write_unknown", inserted, confirmed_rows: committedRows, message: `${committedRows ? `앞의 ${numberWithCommas(committedRows)}행은 저장을 확인했지만 ` : ""}나머지 저장 결과를 확인하지 못했습니다. 같은 파일을 그대로 다시 제출하면 이미 저장된 행은 다시 넣지 않습니다.` }, 503);
    }
    const found = await reconcileImportedTransactionIds(env, householdId, rows.map(row => ({ ...row, source: "my_import" })));
    if (found.size !== rows.length) return jsonResponse({ ok: false, error: "import_write_unknown", inserted, message: "저장된 내용을 파일과 맞춰 보지 못했습니다. 거래 목록에서 결과를 확인해 주세요. 같은 파일을 그대로 다시 제출해도 이미 저장된 행은 다시 넣지 않습니다." }, 503);
    return jsonResponse({ ok: true, inserted, skipped: parsed.skipped + duplicates, duplicates, rows: rows.length, date_samples: rows.slice(0, 5).map(r => r.transaction_date), warnings: parsed.warnings.slice(0, 20) });
  } catch (err) {
    rememberOpsEvent({ kind: "admin_import_failed", severity: "error", path: "/admin/import/json", method: "POST", detail: safeError(err) });
    return jsonResponse({ ok: false, error: "import_failed", message: "가져오기를 완료하지 못했습니다. 거래 목록에서 저장 결과를 확인한 뒤 같은 파일을 다시 제출해 주세요." }, 500);
  }
}

// Recovery candidates change only this build-time gate. No environment switch.
const MY_IMPORT_WRITES_ENABLED_V22959 = true;

async function commitImportedTransactionRows(env, householdId, rows, sourceHash = null, expectedValue = null) {
  if (!MY_IMPORT_WRITES_ENABLED_V22959) throw new Error("import_recovery_read_only");
  if (sourceHash !== null && (!/^[a-f0-9]{64}$/.test(sourceHash) || typeof expectedValue !== "string") || sourceHash === null && expectedValue !== null) throw new Error("import_source_scope_invalid");
  return supabase(env, "/rest/v1/rpc/accountbook_commit_import_v22960", {
    method: "POST", headers: { Prefer: "return=representation" },
    body: JSON.stringify({ p_household_id: householdId, p_rows: rows, p_source_hash: sourceHash, p_expected_value: expectedValue }),
  });
}

function importStorageTextIssue(row = {}) {
  // PostgreSQL LEFT/text length counts Unicode code points, not UTF-16 units.
  for (const [field, max, code] of [["memo", 160, "memo_too_long"], ["payment_method", 40, "payment_too_long"]]) {
    const value = String(row[field] || "");
    if (/\u0000|[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/u.test(value)) return "invalid_field";
    if (Array.from(value).length > max) return code;
  }
  return "";
}

function cleanImportedRowsForInsert(rows = []) {
  const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  return (rows || []).map((row) => {
    const out = { ...row };
    for (const key of Object.keys(out)) if (key.startsWith("_import_")) delete out[key];
    if (!uuidRe.test(String(out.user_id || ""))) delete out.user_id;
    if (!out.payment_method) out.payment_method = "";
    if (!out.memo) out.memo = "";
    if (!out.category) out.category = out.type === "income" ? "기타수입" : "기타지출";
    // V22.9.37 감사 SIM-7: 저장 직전 금액·날짜·구분을 공용 엄격 검증기로 다시 확인한다. Number("0x10")=16 처럼
    // 조용히 바뀌는 값은 저장하지 않고 행을 뺀다.
    out.amount = parseStrictAmount(out.amount, { min: 1 });
    out.transaction_date = parseStrictDate(out.transaction_date);
    return out;
  }).filter((row) => typeof row.household_id === "string" && row.household_id && (row.type === "income" || row.type === "expense") && row.amount !== null && row.transaction_date !== null && !importStorageTextIssue(row));
}

