function allCardIssuers(){return [...new Set(CARD_BENEFIT_CATALOG.map(c=>c.issuer))].sort();}
function findCardBenefit(cardId){return CARD_BENEFIT_CATALOG.find(c=>c.id===cardId)||CARD_BENEFIT_CATALOG[0];}
function normalizeCardText(value=""){return normalizeText(String(value||"")).toLowerCase().replace(/\s+/g,"");}
function cardMatchesRow(card,row){const r=safeObject(row);const text=normalizeCardText(`${r.payment_method||""} ${r.memo||""} ${r.raw_text||""}`);const names=[card.name,card.issuer,...(card.aliases||[])].map(normalizeCardText).filter(Boolean);return names.some(n=>n&&text.includes(n));}
function benefitMatchesRow(benefit,row){const r=safeObject(row);const text=normalizeText(`${r.category||""} ${r.memo||""} ${r.raw_text||""} ${r.payment_method||""}`);if(benefit.category&&normalizeText(r.category||"")===normalizeText(benefit.category))return true;return safeArray(benefit.keywords).some(k=>text.toLowerCase().includes(String(k||"").toLowerCase()));}
function calculateCardBenefitUsage(card,rows=[]){const expenseRows=safeArray(rows).filter(r=>r.type!=="income");const matchedRows=expenseRows.filter(r=>cardMatchesRow(card,r));const usageAmount=matchedRows.reduce((a,r)=>a+Number(r.amount||0),0);const required=Number(card.performance?.monthly_required||0);const benefits=safeArray(card.benefits).map(b=>{const br=matchedRows.filter(r=>benefitMatchesRow(b,r));const spend=br.reduce((a,r)=>a+Number(r.amount||0),0);const rawEstimate=Math.round(spend*Number(b.rate||0));const limit=Number(b.monthly_limit||0);const estimated=b.unlimited?rawEstimate:limit>0?Math.min(limit,rawEstimate):rawEstimate;const remainingLimit=b.unlimited?null:limit>0?Math.max(0,limit-estimated):null;return {...b,spend,estimated,remaining_limit:remainingLimit,count:br.length};});const total=benefits.reduce((a,b)=>a+Number(b.estimated||0),0);const capped=card.total_monthly_limit?Math.min(Number(card.total_monthly_limit),total):total;return {card,matched_count:matchedRows.length,usage_amount:usageAmount,required_performance:required,remaining_performance:Math.max(0,required-usageAmount),performance_rate:required?Math.min(100,Math.round(usageAmount/required*100)):0,estimated_total:capped,remaining_total_limit:card.total_monthly_limit?Math.max(0,Number(card.total_monthly_limit)-capped):null,benefits,matchedRows};}
function renderCardOptions(selectedId="",issuer=""){return CARD_BENEFIT_CATALOG.filter(c=>!issuer||c.issuer===issuer).map(c=>`<option value="${escapeHtml(c.id)}" ${c.id===selectedId?"selected":""}>${escapeHtml(c.issuer)} · ${escapeHtml(c.name)}</option>`).join("");}
function renderIssuerOptions(selected=""){return [`<option value="">카드사 전체</option>`,...allCardIssuers().map(i=>`<option value="${escapeHtml(i)}" ${i===selected?"selected":""}>${escapeHtml(i)}</option>`)].join("");}
function formatBenefitLimit(value,label=""){if(label)return escapeHtml(label);if(value===null||value===undefined)return "약관 확인";const n=Number(value||0);if(!n)return "약관 확인";return `${numberWithCommas(n)}원`;}
function formatBenefitValue(value){if(value===null||value===undefined)return "약관 확인";return `${numberWithCommas(value||0)}원`;}
function renderBenefitRows(calc){const rows=safeArray(calc?.benefits);if(!rows.length)return `<tr><td colspan="6">혜택 기준정보가 없습니다.</td></tr>`;return rows.map(b=>`<tr><td><b>${escapeHtml(b.category||"")}</b><div class="small">${escapeHtml(b.label||"")}</div></td><td>${b.rate?`${Math.round(Number(b.rate||0)*1000)/10}%`:"약관 확인"}</td><td>${formatBenefitLimit(b.monthly_limit,b.monthly_limit_label)}</td><td>${numberWithCommas(b.spend||0)}원</td><td>${formatBenefitValue(b.estimated)}</td><td>${formatBenefitLimit(b.remaining_limit)}</td></tr>`).join("");}
function renderMatchedCardRows(rows=[]){const arr=safeArray(rows).slice(0,80);if(!arr.length)return `<tr><td colspan="7">이 카드로 추정되는 거래가 없습니다. 거래 입력 시 결제수단에 카드명을 남기면 더 정확해집니다.</td></tr>`;return arr.map(r=>`<tr><td>${escapeHtml(String(r.transaction_date||""))}</td><td>${r.type==="income"?"수입":"지출"}</td><td>${numberWithCommas(r.amount||0)}원</td><td>${escapeHtml(r.category||"")}</td><td>${escapeHtml(r.memo||r.raw_text||"")}</td><td>${escapeHtml(r.payment_method||"")}</td><td>${escapeHtml(r.id||"")}</td></tr>`).join("");}
async function buildCardBenefitsPayload(env, url, householdsArg = null) {
  const month = validMonth(url.searchParams.get("month")) || currentMonthKst();
  const households = householdsArg || await fetchAdminHouseholds(env);
  const requestedHouseholdId = String(url.searchParams.get("household_id") || "").trim();
  const selected = selectRequestedScopedHousehold(households, requestedHouseholdId);
  const householdId = selected?.id || "";
  const issuer = String(url.searchParams.get("issuer") || "").trim();
  const selectedCardId = String(url.searchParams.get("card_id") || "").trim();
  const filtered = CARD_BENEFIT_CATALOG.filter((item) => !issuer || item.issuer === issuer);
  const card = filtered.find((item) => item.id === selectedCardId) || findCardBenefit(selectedCardId) || filtered[0] || CARD_BENEFIT_CATALOG[0];
  const rows = householdId ? await fetchAdminRows(env, { month, householdId, type: "all" }) : [];
  const calc = calculateCardBenefitUsage(card, rows);
  return { month, households, householdId, issuer, card, calc, catalog: CARD_BENEFIT_CATALOG };
}
async function handleCardBenefitsPage(request,env,url){const scoped=await getScopedHouseholdsForPage(request,env);if(scoped.scope==="none")return redirectResponse("/my");const {month,households,householdId,issuer,card,calc}=await buildCardBenefitsPayload(env,url,scoped.households);const householdOptions=households.map(h=>`<option value="${escapeHtml(h.id)}" data-household-name="${escapeHtml(householdChoiceLabelV229118(h, households) || h.name || "가계부")}" ${h.id===householdId?"selected":""}>${escapeHtml(householdChoiceLabelV229118(h, households) || h.name)}</option>`).join("");const qs=new URLSearchParams();qs.set("month",month);if(householdId)qs.set("household_id",householdId);qs.set("card_id",card.id);return htmlResponse(`<!doctype html><html lang="ko"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"/><title>카드 혜택 자동조회</title><style>*,*::before,*::after{box-sizing:border-box}body{margin:0;background:#f6f7fb;color:#111827;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans KR",sans-serif;overflow-x:hidden}.wrap{max-width:1180px;margin:0 auto;padding:18px}.hero{background:linear-gradient(135deg,#111827,var(--ab12-action,#5b21b6));color:#fff;border-radius:26px;padding:22px;margin:14px 0;box-shadow:0 18px 40px rgba(15,23,42,.18)}.hero h1{margin:0;font-size:30px}.hero p{line-height:1.6;opacity:.92}.filters{display:grid;grid-template-columns:1.1fr .9fr 1.5fr 150px;gap:8px;margin-top:14px}.filters select,.filters input,.filters button{height:44px;border:1px solid #d1d5db;border-radius:13px;padding:0 12px;background:#fff;font:inherit}.filters button{background:#111827;color:#fff;font-weight:1000}.card{background:#fff;border:1px solid #e5e7eb;border-radius:22px;padding:18px;margin:12px 0;box-shadow:0 10px 28px rgba(15,23,42,.055);overflow:hidden}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(165px,1fr));gap:10px}.metric{background:#fff;border:1px solid #e5e7eb;border-radius:18px;padding:15px}.metric span{display:block;color:#64748b}.metric b{display:block;font-size:24px;margin-top:6px}.progress{height:14px;border-radius:999px;background:#e5e7eb;overflow:hidden}.bar{height:100%;background:#3182F6;border-radius:999px}.btn{display:inline-flex;align-items:center;justify-content:center;min-height:42px;border-radius:13px;background:#111827;color:#fff;text-decoration:none;font-weight:1000;padding:0 13px}.btn.light{background:#eff6ff;color:#1e3a8a}.note{color:#64748b;line-height:1.55}.warnBox{background:#fff7ed;border:1px solid #fed7aa;border-radius:16px;padding:12px;color:#9a3412;line-height:1.55}.tableWrap{overflow-x:auto;-webkit-overflow-scrolling:touch}table{width:100%;border-collapse:collapse;background:#fff;min-width:820px}th,td{border-bottom:1px solid #e5e7eb;padding:10px;text-align:left;font-size:13px;vertical-align:top}.small{font-size:12px;color:#64748b;margin-top:3px}.pill{display:inline-flex;border-radius:999px;background:#ede9fe;color:#5b21b6;padding:5px 9px;font-weight:1000;font-size:12px;margin:2px}@media(max-width:820px){.wrap{padding:12px}.hero h1{font-size:24px}.filters{grid-template-columns:1fr}.card{padding:14px}}</style></head><body>${renderUnifiedNav("card-benefits",{month,householdId,householdName: householdChoiceLabelV229118((households.find((h)=>h.id===householdId)||{}), households) || (households.find((h)=>h.id===householdId)||{}).name,role:String((households.find((h)=>h.id===householdId)||{}).role||"")})}<main class="wrap"><section class="hero"><h1>카드 혜택 자동조회</h1><p>네이버페이 카드 페이지 기준으로 정리한 카드사/혜택 요약을 드롭다운으로 선택하고, 이번 달 거래와 매칭해 실적/혜택 한도를 계산합니다.</p><form class="filters" method="get" action="/card-benefits"><select name="household_id">${householdOptions}</select><input type="month" name="month" value="${escapeHtml(month)}"/><select name="issuer" onchange="this.form.submit()">${renderIssuerOptions(issuer)}</select><select name="card_id">${renderCardOptions(card.id,issuer)}</select><button type="submit">조회</button></form></section><section class="card"><h2>${escapeHtml(card.name)}</h2><p><span class="pill">${escapeHtml(card.issuer)}</span><span class="pill">${escapeHtml(card.performance?.label||"")}</span><span class="pill">통합 한도 ${numberWithCommas(card.total_monthly_limit||0)}원</span></p><p class="warnBox">${escapeHtml(card.notes||"카드 혜택 문서 기준정보는 운영 전 검수가 필요합니다.")}</p><div class="grid"><div class="metric"><span>이번 달 추정 사용액</span><b>${numberWithCommas(calc.usage_amount)}원</b></div><div class="metric"><span>실적 기준</span><b>${numberWithCommas(calc.required_performance)}원</b></div><div class="metric"><span>실적까지 남은 금액</span><b>${numberWithCommas(calc.remaining_performance)}원</b></div><div class="metric"><span>예상 혜택</span><b>${numberWithCommas(calc.estimated_total)}원</b></div><div class="metric"><span>남은 통합 한도</span><b>${formatBenefitValue(calc.remaining_total_limit)}</b></div><div class="metric"><span>매칭 거래</span><b>${numberWithCommas(calc.matched_count)}건</b></div></div><p class="note">실적 달성률 ${calc.performance_rate}%</p><div class="progress"><div class="bar" style="width:${Math.min(100,calc.performance_rate)}%"></div></div><p><a class="btn light" href="/payment-methods?${escapeHtml(qs.toString())}">결제수단 연결 안내</a></p><p class="note">${escapeHtml(NAVER_CARD_SOURCE_NOTE)}</p></section><section class="card"><h2>혜택 카테고리별 현황</h2><div class="tableWrap"><table><thead><tr><th>혜택</th><th>율</th><th>월 한도</th><th>매칭 지출</th><th>예상 혜택</th><th>남은 한도</th></tr></thead><tbody>${renderBenefitRows(calc)}</tbody></table></div></section><section class="card"><h2>카드 매칭 거래</h2><p class="note">거래의 결제수단/메모에 카드명 또는 별칭이 포함된 경우 매칭합니다. 다음 단계에서 결제수단 등록과 연결하면 더 정확해집니다.</p><div class="tableWrap"><table><thead><tr><th>거래일</th><th>유형</th><th>금액</th><th>분류</th><th>메모</th><th>결제수단</th><th>ID</th></tr></thead><tbody>${renderMatchedCardRows(calc.matchedRows)}</tbody></table></div></section></main></body></html>`);}

function shiftMonthKey(month = "", delta = 0) {
  const m = validMonth(month) || currentMonthKst();
  const [y, mo] = m.split("-").map(Number);
  const d = new Date(Date.UTC(y, mo - 1 + delta, 1));
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}`;
}

function formatMoneyShortKo(n) {
  const v = Math.round(Number(n || 0));
  const abs = Math.abs(v);
  const sign = v < 0 ? "-" : "";
  if (abs >= 100000000) {
    const eok = abs / 100000000;
    const num = eok >= 10 ? Math.round(eok).toLocaleString("ko-KR") : String(Math.round(eok * 10) / 10);
    return `${sign}${num}억`;
  }
  if (abs >= 10000) return `${sign}${Math.round(abs / 10000).toLocaleString("ko-KR")}만`;
  return `${sign}${abs.toLocaleString("ko-KR")}원`;
}

function paymentAssetFreshness(a = {}) {
  const t = Date.parse(a.balance_updated_at || a.updated_at || "");
  if (!Number.isFinite(t) || t < Date.parse("2001-01-01T00:00:00Z")) return { label: "잔액 업데이트 필요", stale: true };
  const days = Math.floor((Date.now() - t) / 86400000);
  if (days <= 0) return { label: "오늘 업데이트", stale: false };
  if (days === 1) return { label: "어제 업데이트", stale: false };
  if (days < 31) return { label: `${days}일 전 업데이트`, stale: days >= 14 };
  return { label: `${Math.floor(days / 30)}달 전 업데이트`, stale: true };
}

function cardUsageMatchScore(pm, card) {
  const nm = normalizeText(card?.name || "");
  const issuer = normalizeText(card?.issuer || "");
  if (nm && pm === nm) return 3000 + nm.length;
  if (nm && pm.includes(nm)) return 2000 + nm.length;
  if (issuer && issuer.length >= 2 && pm.includes(issuer) && /카드/.test(pm)) return 1000 + issuer.length;
  return 0;
}

function computeCardUsageMap(assets = [], rows = []) {
  const cards = safeArray(assets).filter((a) => paymentAssetKindMeta(a.kind).group === "card");
  const usage = Object.create(null);
  for (const c of cards) usage[c.id] = { count: 0, amount: 0 };
  if (!cards.length) return usage;
  for (const r of safeArray(rows)) {
    if (String(r.type) === "income") continue;
    const pm = normalizeText(r.payment_method || "");
    if (!pm) continue;
    // V22.9.109 G-4(Gemini ④): 어떻게 맞았는지를 먼저 본다 — 이름 일치 > 이름 포함 > 발급사(2자 이상 + ‘카드’) 순. 같은 단계 안에서는 더 긴
    // 이름(더 구체적인 카드)이 이기고 그것도 같으면 목록 앞 카드다. 예전에는 단계와 무관하게 이름 길이만 비교해(`nm.length >= bestLen`) 이름으로
    // 정확히 맞은 ‘신한카드 Mr.Life’ 가 발급사로만 맞은 더 긴 이름의 ‘신한카드 Deep Dream’ 에 졌고, 길이가 같으면 목록 뒤 카드가 가져갔다.
    let best = null;
    let bestScore = 0;
    for (const c of cards) {
      const score = cardUsageMatchScore(pm, c);
      if (score > bestScore) { best = c; bestScore = score; }
    }
    if (best) {
      usage[best.id].count += 1;
      usage[best.id].amount += Number(r.amount || 0);
    }
  }
  return usage;
}

function findPaymentAssetForMethod(methodName = "", assets = []) {
  const method = normalizeText(methodName);
  if (!method || method === "미지정") return null;
  const candidates = safeArray(assets).map((asset) => {
    const name = normalizeText(asset.name);
    const issuer = normalizeText(asset.issuer || "");
    let score = 0;
    if (name && method === name) score = 1000 + name.length;
    else if (name && (method.includes(name) || name.includes(method))) score = 500 + Math.min(name.length, method.length);
    else if (issuer.length >= 2 && method.includes(issuer)) score = 200 + issuer.length;
    return { asset, score };
  }).filter((item) => item.score > 0).sort((a, b) => b.score - a.score);
  return candidates[0]?.asset || null;
}

function guessAssetKindFromMethodName(name = "") {
  const t = normalizeText(name);
  if (/체크/.test(t)) return "check_card";
  if (/카드/.test(t)) return "credit_card";
  if (/(페이|토스|포인트)/.test(t)) return "easy_pay";
  if (/현금/.test(t)) return "cash";
  if (/(통장|계좌|이체|은행|뱅크)/.test(t)) return "bank_account";
  return "credit_card";
}

