    if (!commit && !body.get("csv_text") && !(body.get("csv_file") && body.get("csv_file").size)) { message("원본이 현재 탭에 없습니다. 같은 파일을 다시 선택하거나 내용을 다시 붙여넣어 주세요.", true); document.getElementById("myImportFile").focus(); return; }
