  form.addEventListener("change", function(event) { if (event.target.matches('[name="date_basis_mode"],[name="month"],[name="skip_duplicates"],[name="household_id"]')) invalidate(false, "분석 기준이 바뀌었습니다. 다시 분석한 뒤 저장할 행을 선택해 주세요."); });
