        box.appendChild(el("span", "iChip " + (bad ? "bad" : "good"), pw.label + "보다 관측 " + compLabel() + " " + Math.abs(d) + "% " + (d > 0 ? "증가" : "감소") + " (" + model.observed.start + " ~ " + model.observed.end + " / " + pw.start + " ~ " + pw.end + ")"));
