  BUDGET_SETUP: { risk: "money_setting", targets: ["예산"], actions: ["설정","변경","수정","바꾸기","잡기","정하기","복사"] },
  BUDGET_STATUS: { risk: "read", targets: ["예산","남은 돈","잔여 금액","쓸 수 있는 돈"], actions: ["확인","조회","현황","얼마 남았","얼마나 남았","사용률","잔액","남은","보여줘","알려줘"] },
