    category: String(o.category || "").slice(0, 80),
    // V22.9.131 (독립 검토 1): 화면은 스냅숏의 메모로 표식을 다시 만든다. 200자에서 자르면 원문이 긴 기록(메모 없이 원문 500자까지)의 표식이 달라진다.
    memo: String(o.memo || "").slice(0, 500),
